#include <string.h>
typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
/* returns number of matvecs, or -1 on unexpected ido */
int run(void *fn, void *state, double *resid, double *v, int *ipntr,
        double *workd, double *workl, int n,
        const int *indptr, const int *indices, const double *data)
{
    naupd_t f = (naupd_t)fn;
    int *ido = (int*)((char*)state + 0x34);
    int cnt = 0;
    for (;;) {
        f(state, resid, v, n, ipntr, workd, workl);
        int c = *ido;
        if (c == 1 || c == 5) {
            const double *x = workd + ipntr[0];
            double *y = workd + ipntr[1];
            for (int i = 0; i < n; i++) {
                double s = 0.0;
                for (int p = indptr[i]; p < indptr[i+1]; p++) s += data[p] * x[indices[p]];
                y[i] = s;
            }
            cnt++;
        } else if (c == 2) {
            memcpy(workd + ipntr[1], workd + ipntr[0], sizeof(double)*n);
        } else if (c == 99) {
            return cnt;
        } else {
            return -1 - c;
        }
    }
}
