void my_dtrevc(const char*side,const char*howmny,int*sel,const int*N,const double*T,const int*LDT,
  double*VL,const int*LDVL,double*VR,const int*LDVR,const int*MM,int*M,double*work,int*info) SYM(dtrevc);
void my_dtrevc(const char*side,const char*howmny,int*sel,const int*N,const double*T,const int*LDT,
  double*VL,const int*LDVL,double*VR,const int*LDVR,const int*MM,int*M,double*work,int*info){
