  *info=0; *M=n;
  if(n==0) return;
#define t(i,j) T[(i)+(long)(j)*ldt]
  double complex x[256];
  double re[256], im[256];
  double unfl=DBL_MIN, ulp=DBL_EPSILON, smlnum=unfl*(n/ulp);
  int ki=n-1;
