    int pair = (ki>0 && t(ki,ki-1)!=0.0);
    double complex lam; int top;
    if(!pair){
      lam=t(ki,ki); top=ki;
      for(int k=0;k<=ki;k++) x[k]=0;
      x[ki]=1.0;
      for(int k=0;k<ki;k++) x[k]=-t(k,ki);
    } else {
      int k0=ki-1;
      double wr=t(ki,ki), wi=sqrt(fabs(t(k0,ki)))*sqrt(fabs(t(ki,k0)));
      lam=wr+I*wi; top=k0;
      double complex x1,x2;
      if(fabs(t(k0,ki))>=fabs(t(ki,k0))){ x1=1.0; x2=I*(wi/t(k0,ki)); }
