        for(int r=0;r<n;r++){ double ar=0,ai=0; for(int k=0;k<=ki;k++){ double q=VR[r+(long)k*ldvr]; ar+=q*creal(x[k]); ai+=q*cimag(x[k]); } re[r]=ar; im[r]=ai; }
