#include <immintrin.h>
#include <string.h>
/* SELL-4: groups of 4 rows (perm order), each group g has len[g] slots, stored interleaved:
   val[off[g] + 4*k + r], col[...]. Output y[perm[4g+r]]. */
static inline void sellmv(int ng,const int*off,const int*len,const int*perm,const int*col,const double*val,const double*x,double*y){
  for(int g=0;g<ng;g++){
    __m256d s=_mm256_setzero_pd();
    const int*c=col+off[g]; const double*v=val+off[g]; int L=len[g];
    for(int k=0;k<L;k++){
      __m128i ci=_mm_loadu_si128((const __m128i*)(c+4*k));
      __m256d xv=_mm256_i32gather_pd(x,ci,8);
      __m256d vv=_mm256_loadu_pd(v+4*k);
      s=_mm256_add_pd(s,_mm256_mul_pd(vv,xv));
    }
    double o[4]; _mm256_storeu_pd(o,s);
    const int*p=perm+4*g;
    y[p[0]]=o[0]; y[p[1]]=o[1]; y[p[2]]=o[2]; y[p[3]]=o[3];
  }
}
