import numpy as np
def build_sell(A):
    n=A.shape[0]; ip=A.indptr; rl=np.diff(ip)
    perm=np.argsort(-rl,kind='stable').astype(np.int32)
    ng=(n+3)//4; pad=ng*4-n
    permp=np.concatenate([perm,np.full(pad,n,np.int32)])  # dummy row n
    rlp=np.concatenate([rl,[0]])[permp].reshape(ng,4)
    lens=rlp.max(1).astype(np.int32)
    off=np.zeros(ng,np.int32); off[1:]=np.cumsum(4*lens)[:-1]
    tot=int(4*lens.sum())
    col=np.zeros(tot,np.int32); val=np.zeros(tot)
    for g in range(ng):
        for r in range(4):
            row=permp[4*g+r]
            if row==n: continue
            a,b=ip[row],ip[row+1]
            idx=off[g]+4*np.arange(b-a)+r
            col[idx]=A.indices[a:b]; val[idx]=A.data[a:b]
    return ng,off,lens,permp,col,val
