typedef void (*naupd_t)(void*, double*, double*, int, int*, double*, double*);
int run(void *fn, void *state, double *resid, double *v, int *ipntr,
        double *workd, double *workl, int n,
        int ng, const int *off, const int *len, const int *perm,
        const int *col, const double *val, double *ybuf)
{
    naupd_t f = (naupd_t)fn;
    int *ido = (int*)((char*)state + 0x34);
    int cnt = 0;
    for (;;) {
        f(state, resid, v, n, ipntr, workd, workl);
        int c = *ido;
        if (c == 1 || c == 5) {
            sellmv(ng, off, len, perm, col, val, workd + ipntr[0], ybuf);
            memcpy(workd + ipntr[1], ybuf, sizeof(double)*n);
            cnt++;
        } else if (c == 2) {
            memcpy(workd + ipntr[1], workd + ipntr[0], sizeof(double)*n);
        } else if (c == 99) {
            return cnt;
        } else {
            return -1 - c;
        }
    }
}
